"""Protobuf gRPC against the real grpcio, including a stub generated by protoc as an independent client/server."""

from __future__ import annotations

import asyncio
import importlib.util
import sys
import tempfile
from pathlib import Path
from typing import Any

import grpc
import pytest
from grpc_tools import protoc

from austial import Controller, Module
from austial.microservices import (
    ClientOptions,
    ClientProxy,
    GrpcMethod,
    MicroserviceOptions,
    Payload,
    RpcError,
    RpcException,
    Transport,
    create_microservice,
)

PROTO = str(Path(__file__).parent / "protos" / "hero.proto")


@Controller()
class HeroController:
    @GrpcMethod("HeroService")
    def find_one(self, data: dict = Payload()):
        if data["id"] == 404:
            raise RpcException({"message": "no such hero", "code": 5})  # NOT_FOUND
        if data["id"] == 403:
            raise RpcException("Forbidden resource")
        return {"id": data["id"], "name": f"hero-{data['id']}", "rank": "HERO", "tags": ["a", "b"]}

    @GrpcMethod("HeroService", "FindMany")
    async def many(self, data: dict = Payload()):
        for n in range(data["count"]):
            yield {"id": n, "name": f"h{n}"}

    @GrpcMethod("HeroService")
    async def sum(self, numbers=Payload()):
        return {"value": sum([n["value"] async for n in numbers])}

    @GrpcMethod("HeroService")
    async def chat(self, lines=Payload()):
        async for line in lines:
            yield {"text": line["text"].upper()}


@Module(controllers=[HeroController])
class App:
    pass


async def start(**extra):
    server = create_microservice(App, MicroserviceOptions(Transport.GRPC, port=0, extra={"proto_path": PROTO, **extra}))
    await server.listen()
    return server, server.server.transport.port  # type: ignore[attr-defined]


def client_for(port: int) -> ClientProxy:
    return ClientProxy(ClientOptions("H", Transport.GRPC, port=port, timeout=5, extra={"proto_path": PROTO}))


async def test_all_four_call_kinds_between_austial_client_and_server() -> None:
    server, port = await start()
    heroes = client_for(port)
    await heroes.connect()
    try:
        service = heroes.get_service("HeroService")
        assert await service.find_one({"id": 7}) == {"id": 7, "name": "hero-7", "rank": "HERO", "tags": ["a", "b"]}
        assert await service.FindOne({"id": 1}) == await service.find_one({"id": 1})  # exact or snake_case names
        assert [h["id"] async for h in service.find_many({"count": 3})] == [0, 1, 2]
        assert await service.sum([{"value": 1}, {"value": 2}, {"value": 39}]) == {"value": 42}

        async def lines():
            for text in ("a", "b", "c"):
                yield {"text": text}

        assert [m["text"] async for m in service.chat(lines())] == ["A", "B", "C"]
        assert await heroes.send("HeroService/FindOne", {"id": 3}) == await service.find_one({"id": 3})
    finally:
        await heroes.close()
        await server.close()


async def test_errors_map_to_grpc_status_codes() -> None:
    server, port = await start()
    heroes = client_for(port)
    await heroes.connect()
    try:
        service = heroes.get_service("HeroService")
        with pytest.raises(RpcError) as missing:
            await service.find_one({"id": 404})
        assert missing.value.payload["code"] == grpc.StatusCode.NOT_FOUND.value[0]
        assert missing.value.payload["message"] == "no such hero"
        with pytest.raises(RpcError) as forbidden:
            await service.find_one({"id": 403})
        assert forbidden.value.payload["code"] == grpc.StatusCode.PERMISSION_DENIED.value[0]
        with pytest.raises(AttributeError):
            service.nope  # noqa: B018
        with pytest.raises(LookupError):
            heroes.get_service("Nope")
        with pytest.raises(NotImplementedError):
            await heroes.emit("x", None)
    finally:
        await heroes.close()
        await server.close()


def generated_stubs() -> list[Any]:
    """What any other language (or protoc's own Python plugin) would use: an independent gRPC implementation."""
    out = Path(tempfile.mkdtemp())
    args = ["protoc", f"-I{Path(PROTO).parent}", f"--python_out={out}", f"--grpc_python_out={out}", "hero.proto"]
    assert protoc.main(args) == 0
    sys.path.insert(0, str(out))
    try:
        modules = []
        for name in ("hero_pb2", "hero_pb2_grpc"):
            spec = importlib.util.spec_from_file_location(name, out / f"{name}.py")
            assert spec is not None and spec.loader is not None
            module = importlib.util.module_from_spec(spec)
            sys.modules[name] = module
            spec.loader.exec_module(module)
            modules.append(module)
        return modules
    finally:
        sys.path.remove(str(out))


async def test_protoc_generated_stub_can_call_the_austial_server() -> None:
    pb2, pb2_grpc = generated_stubs()
    server, port = await start()
    try:
        async with grpc.aio.insecure_channel(f"127.0.0.1:{port}") as channel:
            stub = pb2_grpc.HeroServiceStub(channel)
            hero = await stub.FindOne(pb2.HeroById(id=9))
            assert (hero.id, hero.name, hero.rank, list(hero.tags)) == (9, "hero-9", pb2.HERO, ["a", "b"])
            assert [h.id async for h in stub.FindMany(pb2.Query(count=2))] == [0, 1]

            async def numbers():
                for n in (5, 6):
                    yield pb2.Number(value=n)

            assert (await stub.Sum(numbers())).value == 11
            replies = [m.text async for m in stub.Chat(iter_lines(pb2))]
            assert replies == ["X", "Y"]
            with pytest.raises(grpc.aio.AioRpcError) as caught:
                await stub.FindOne(pb2.HeroById(id=404))
            assert caught.value.code() == grpc.StatusCode.NOT_FOUND
    finally:
        await server.close()


async def iter_lines(pb2):
    for text in ("x", "y"):
        yield pb2.Line(text=text)


async def test_austial_client_can_call_a_protoc_generated_server() -> None:
    pb2, pb2_grpc = generated_stubs()

    servicer_base: Any = pb2_grpc.HeroServiceServicer

    class Servicer(servicer_base):
        async def FindOne(self, request, context):  # noqa: N802
            return pb2.Hero(id=request.id, name="from-stub", rank=pb2.VILLAIN, tags=["z"])

        async def FindMany(self, request, context):  # noqa: N802
            for n in range(request.count):
                yield pb2.Hero(id=n)

        async def Sum(self, request_iterator, context):  # noqa: N802
            return pb2.Number(value=sum([m.value async for m in request_iterator]))

        async def Chat(self, request_iterator, context):  # noqa: N802
            async for m in request_iterator:
                yield pb2.Line(text=m.text * 2)

    other = grpc.aio.server()
    pb2_grpc.add_HeroServiceServicer_to_server(Servicer(), other)
    port = other.add_insecure_port("127.0.0.1:0")
    await other.start()
    heroes = client_for(port)
    await heroes.connect()
    try:
        service = heroes.get_service("HeroService")
        assert await service.find_one({"id": 2}) == {"id": 2, "name": "from-stub", "rank": "VILLAIN", "tags": ["z"]}
        assert [h["id"] async for h in service.find_many({"count": 2})] == [0, 1]
        assert await service.sum([{"value": 4}, {"value": 5}]) == {"value": 9}
        assert [m["text"] async for m in service.chat([{"text": "ab"}])] == ["abab"]
    finally:
        await heroes.close()
        await other.stop(0)


async def test_serves_only_the_listed_services_and_rejects_a_bad_proto(tmp_path) -> None:
    server, port = await start(services=[])  # nothing served
    heroes = client_for(port)
    await heroes.connect()
    try:
        with pytest.raises(RpcError) as caught:
            await heroes.get_service("HeroService").find_one({"id": 1})
        assert caught.value.payload["code"] == grpc.StatusCode.UNIMPLEMENTED.value[0]
    finally:
        await heroes.close()
        await server.close()

    bad = tmp_path / "bad.proto"
    bad.write_text("syntax = 'proto3'; message {")
    with pytest.raises(ValueError, match="protoc could not compile"):
        create_microservice(App, MicroserviceOptions(Transport.GRPC, extra={"proto_path": str(bad)}))
    assert asyncio.get_running_loop()
